from dataclasses import dataclass, field


@dataclass
class AbstractRmod:
    program: str = ""
    master_node_ids: tuple[int, ...] = (0,)
    default_switch_slave_node_id: int = 1
    node_switch_time: int = 127
    switch_commands: tuple[str, ...] = ()
    product_names: tuple[str] = field(init=False)


@dataclass
class AbstractRmodGeneration5dot1(AbstractRmod):
    switch_commands: tuple[str, ...] = ("devmem 0xFFB08078 32 0x41", "devmem 0xFFB08078 32 0x40")


@dataclass
class AbstractRmodGeneration6dot1(AbstractRmod):
    switch_commands: tuple[str, ...] = (
        "sudo devmem 0xf9040020 w 0",
        "sudo devmem 0xf9040020 w 0x8",
        "sudo devmem 0xf9040020 w 0x9",
    )


@dataclass
class AbstractRmodGeneration6dot2(AbstractRmod):
    master_node_ids = (0, 17, 18)
    pass


@dataclass
class AbstractRmodGeneration7dot1(AbstractRmod):
    switch_commands: tuple[str, ...] = (
        "echo out > /sys/class/gpio/gpio350/direction && sleep 0.5 && "
        "echo out > /sys/class/gpio/gpio297/direction && sleep 0.5 && "
        "echo 0 > /sys/class/gpio/gpio297/value && sleep 0.5 && "
        "echo 0 > /sys/class/gpio/gpio350/value",
        "echo 350 > /sys/class/gpio/export && sleep 0.5 && "
        "echo 297 > /sys/class/gpio/export && sleep 0.5 && "
        "echo out > /sys/class/gpio/gpio350/direction && sleep 0.5 && "
        "echo out > /sys/class/gpio/gpio297/direction && sleep 0.5 && "
        "echo 1 > /sys/class/gpio/gpio297/value && sleep 0.5 && "
        "echo 0 > /sys/class/gpio/gpio350/value",
        "echo 350 > /sys/class/gpio/export && sleep 0.5 && "
        "echo 297 > /sys/class/gpio/export && sleep 0.5 && "
        "echo out > /sys/class/gpio/gpio350/direction && sleep 0.5 && "
        "echo out > /sys/class/gpio/gpio297/direction && sleep 0.5 && "
        "echo 0 > /sys/class/gpio/gpio297/value && sleep 0.5 && "
        "echo 1 > /sys/class/gpio/gpio350/value",
        "echo 350 > /sys/class/gpio/export && sleep 0.5 && "
        "echo 297 > /sys/class/gpio/export && sleep 0.5 && "
        "echo out > /sys/class/gpio/gpio350/direction && sleep 0.5 && "
        "echo out > /sys/class/gpio/gpio297/direction && sleep 0.5 && "
        "echo 1 > /sys/class/gpio/gpio297/value && sleep 0.5 && "
        "echo 1 > /sys/class/gpio/gpio350/value",
    )


